		},
		{
			title = "Sin registro",
			text = [=[Nadie sabe cuánto tiempo ha vivido Saltspine allá abajo, ni de qué se ha alimentado en la oscuridad. Su nombre es todo lo que los excavadores le han dado.]=],
		},
	},
	bonds = {
		{ id = "shadetooth", name = "Shadetooth", note = "comparte con él las profundidades" },
	},
})

